mapper.select:
SELECT COUNT(*) AS calls, COALESCE(SUM(input_tokens), 0) AS inputTokens,
       COALESCE(SUM(output_tokens), 0) AS outputTokens, COALESCE(SUM(latency_ms), 0) AS latencyMs,
       SUM(cost_cny) AS costCny, SUM(CASE WHEN cost_cny IS NULL THEN 1 ELSE 0 END) AS unpriced
FROM llm_call
WHERE id > #{afterId}
AND purpose = #{purpose}
